return ['domain'=>'zinn-offload','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ne_NP','project-id-version'=>'zinn-offload','pot-creation-date'=>'2026-10-02T10:28:39+00:00','po-revision-date'=>'2026-10-02T10:28:39+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Media Offload'=>'Zinn® Media Offload','https://zinndigital.com/wordpress-plugins/zinn-offload'=>'https://zinndigital.com/wordpress-plugins/zinn-offload','Moves this site\'s media library to Zinn® object storage and serves it from a CDN. Configured from your Zinn® dashboard — no access key is ever typed into WordPress.'=>'यो साइटको मिडिया लाइब्रेरीलाई Zinn® अब्जेक्ट स्टोरेजमा सार्छ र यसलाई CDN बाट सेवा दिन्छ। तपाईंको Zinn® ड्यासबोर्डबाट कन्फिगर गरिएको छ — WordPress मा कहिल्यै कुनै पहुँच कुञ्जी टाइप गरिँदैन।','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'भण्डारण गरियो। यसलाई बदल्न नयाँ मान टाइप गर्नुहोस्।','Filter this list…'=>'यो सूची फिल्टर गर्नुहोस्…','Filter this list'=>'यो सूची फिल्टर गर्नुहोस्','Nothing matches that filter.'=>'त्यो फिल्टरसँग केही पनि मेल खाँदैन।','Add a row'=>'पङ्क्ति थप्नुहोस्','Remove this row'=>'यो पङ्क्ति हटाउनुहोस्','Remove'=>'हटाउनुहोस्','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — अवलोकन','Overview'=>'सिंहावलोकन','Copied'=>'प्रतिलिपि गरियो','Every Zinn® plugin on this site, and whether it is working.'=>'यस साइटमा भएको प्रत्येक Zinn® प्लगइन, र यो काम गरिरहेको छ वा छैन।','No connection is needed for this plugin.'=>'यो प्लगइनको लागि कुनै जडान आवश्यक छैन।','Open settings'=>'सेटिङहरू खोल्नुहोस्','You do not have permission to change these settings.'=>'तपाईँसँग यी सेटिङहरू परिवर्तन गर्ने अनुमति छैन।','Settings sections'=>'सेटिङ खण्डहरू','Support'=>'सहयोग','Save changes'=>'परिवर्तनहरू बचत गर्नुहोस्','Tools'=>'उपकरणहरू','Export settings'=>'सेटिङहरू निर्यात गर्नुहोस्','Reset to defaults'=>'पूर्वनिर्धारितमा रिसेट गर्नुहोस्','This puts every setting on this plugin back to its default. Continue?'=>'यसले यो प्लगइनको प्रत्येक सेटिङलाई पूर्वनिर्धारितमा फर्काउँछ। के जारी राख्न चाहनुहुन्छ?','Diagnostics for support'=>'सहयोगका लागि निदान','Import a settings file'=>'सेटिङ फाइल आयात गर्नुहोस्','Import'=>'आयात गर्नुहोस्','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'निर्यात गरिएका फाइलहरूमा कहिल्यै पनि पासवर्ड, टोकन वा API कुञ्जीहरू हुँदैनन् — तपाईंले नयाँ साइटमा ती फेरि प्रविष्ट गर्नुपर्नेछ।','Settings saved.'=>'सेटिङहरू सुरक्षित गरियो।','Every setting on this plugin is back to its default.'=>'यस प्लगइनको प्रत्येक सेटिङ पूर्वनिर्धारितमा फर्किएको छ।','Done.'=>'सम्पन्न भयो।','That action is not available.'=>'त्यो कार्य उपलब्ध छैन।','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'त्यो फाइल पढ्न सकिएन। Zinn® प्लगइनबाट निर्यात गरिएको सेटिङ फाइल छान्नुहोस्।','That file is too large to be a settings export.'=>'त्यो फाइल सेटिङ निर्यात हुनका लागि धेरै ठूलो छ।','That file is not a Zinn® settings export.'=>'त्यो फाइल Zinn® सेटिङ निर्यात होइन।','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'त्यो फाइल फरक प्लगइन (%s) बाट निर्यात गरिएको थियो, त्यसैले यसलाई यहाँ आयात गर्दा यो प्लगइनले नबुझ्ने सेटिङहरू भण्डारण हुनेछ।','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'%d सेटिङ आयात गरियो। पासवर्ड र API कुञ्जीहरू निर्यातमा कहिल्यै समावेश हुँदैनन्, त्यसैले कृपया तिनलाई पुन: प्रविष्ट गर्नुहोस्।' . "\0" . '%d सेटिङहरू आयात गरियो। पासवर्ड र API कुञ्जीहरू निर्यातमा कहिल्यै समावेश हुँदैनन्, त्यसैले कृपया ती फेरि प्रविष्ट गर्नुहोस्।','Zinn Digital® did not return a token. Nothing has been changed on this site.'=>'Zinn Digital® ले टोकन फिर्ता गरेन। यो साइटमा केही पनि परिवर्तन गरिएको छैन।','This site is no longer connected to Zinn® media offload. New uploads will stay on this server. Pair it again from your Zinn Digital® dashboard.'=>'यो साइट अब Zinn® मिडिया अफलोडमा जडान गरिएको छैन। नयाँ अपलोडहरू यसै सर्भरमा रहनेछन्। यसलाई आफ्नो Zinn Digital® ड्यासबोर्डबाट फेरि जोडा बनाउनुहोस्।','Zinn Digital® answered with HTTP %d.'=>'Zinn Digital® ले HTTP %d मार्फत जवाफ दियो।','Disconnected by Zinn Digital®.'=>'Zinn Digital® द्वारा विच्छेद गरिएको।','Connected'=>'जडान गरियो','Connecting…'=>'जडान हुँदैछ…','Connected, but something needs attention'=>'जडान भयो, तर केही कुरामा ध्यान दिन आवश्यक छ','Not connected'=>'जडान भएको छैन','Running on your own account'=>'तपाईंको आफ्नै खातामा चल्दै छ','We could not check this'=>'हामीले यो जाँच गर्न सकेनौं','This plugin did not say why. Send a diagnostics report and we will look.'=>'यो प्लगइनले कारण खुलाएन। एक निदान प्रतिवेदन पठाउनुहोस् र हामी हेर्नेछौं।','Connection status'=>'जडान स्थिति','Last checked %s ago.'=>'अन्तिम पटक %s अघि जाँच गरियो।','(opens in a new tab)'=>'(नयाँ ट्याबमा खुल्छ)','Send this to Zinn® support'=>'यसलाई Zinn® समर्थनमा पठाउनुहोस्','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'पठाइने कुरा ठ्याक्कै यही हो — अरू केही पनि होइन, र केही लुकेको पनि छैन। तपाईंका पासवर्डहरू, टोकनहरू र API कुञ्जीहरू यसमा छैनन्।','The diagnostics report that will be sent'=>'पठाइने निदान रिपोर्ट','Copy to clipboard'=>'क्लिपबोर्डमा प्रतिलिपि गर्नुहोस्','Send this report to Zinn® support'=>'यो प्रतिवेदन Zinn® समर्थनलाई पठाउनुहोस्','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'हामी तपाईंको लागि एउटा समर्थन टिकट खोल्छौं र इमेल मार्फत जवाफ दिन्छौं। यदि तपाईं यसलाई पठाउन चाहनुहुन्न भने, माथिको प्रतिलिपि गर्नुहोस् र आफैं टिकटमा टाँस्नुहोस्।','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'हामी यो सर्भर (%s) बाट Zinn Digital® मा पुग्न सकेनौं। माथिको रिपोर्ट प्रतिलिपि गर्नुहोस् र यसको सट्टा टिकट खोल्नुहोस् — तपाईंको सेटिङहरूमा केही पनि गलत छैन।','Sent. Zinn® support has your report and will reply by email.'=>'पठाइयो। Zinn® समर्थनले तपाईंको रिपोर्ट प्राप्त गरेको छ र इमेल मार्फत जवाफ दिनेछ।','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'पठाइयो। Zinn® समर्थनले तपाईंको रिपोर्ट प्राप्त गरेको छ — सन्दर्भ %s — र इमेलमार्फत जवाफ दिनेछ।','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'तपाईंले छोटो समयमा धेरै रिपोर्टहरू पठाउनुभएको छ। केही मिनेट पर्खनुहोस् र पुन: प्रयास गर्नुहोस् — अघिल्ला रिपोर्टहरू प्राप्त भइसकेका छन्।','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® ले भर्खरै प्रतिवेदन स्वीकार गर्न सकेन — यो हाम्रो तर्फबाट भएको समस्या हो, तपाईंको तर्फबाट होइन। केही बेरपछि फेरि प्रयास गर्नुहोस्, वा माथिको प्रतिवेदनलाई टिकटमा प्रतिलिपि गर्नुहोस्।','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'प्रतिवेदन अस्वीकार गरियो (HTTP %d)। यसलाई माथि प्रतिलिपि गर्नुहोस् र सो नम्बर उद्धृत गर्दै टिकट खोल्नुहोस्।','%s — guides and services'=>'%s — मार्गदर्शिका र सेवाहरू','User guides'=>'प्रयोगकर्ता गाइडहरू','Read the %s user guide'=>'%s प्रयोगकर्ता पुस्तिका पढ्नुहोस्','Hide this'=>'यो लुकाउनुहोस्','Zinn® hosting for WordPress'=>'WordPress का लागि Zinn® होस्टिङ','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, दैनिक ब्याकअप, नि:शुल्क स्थानान्तरण र एक भन्दा बढी साइट चलाउने व्यक्तिहरूका लागि बनाइएको नियन्त्रण प्यानल।','The Zinn® marketplace'=>'Zinn® बजार','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'दुवै पक्ष सन्तुष्ट नभएसम्म रकम सुरक्षित रूपमा राखेर स्थापित साइटहरू, डोमेनहरू र लिङ्क प्लेसमेन्टहरू खरिद तथा बिक्री गर्नुहोस्।','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — यो कामलाई नै आफ्नो पेशा बनाएका व्यक्तिहरूलाई नियुक्त गर्नुहोस्','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'हाम्रो विश्वव्यापी फ्रिलान्स बजार: लेखक, डिजाइनर, विकासकर्ता र SEO विशेषज्ञहरूबाट १०,००० भन्दा बढी तयारी सेवाहरू ब्राउज गर्नुहोस्, वा कुनै परियोजना पोस्ट गरी उनीहरूलाई बोलपत्र पेश गर्न दिनुहोस्।','Media Offload'=>'मिडिया अफलोड','Connection'=>'जडान','What gets moved'=>'के सारिन्छ','How media is served'=>'मिडिया कसरी सेवा दिइन्छ','Move a batch now'=>'अहिले एउटा ब्याच सार्नुहोस्','Media already moved is never affected by a change here — its address does not change.'=>'पहिल्यै सारिएको मिडिया यहाँको परिवर्तनबाट कहिल्यै प्रभावित हुँदैन — यसको ठेगाना परिवर्तन हुँदैन।','New uploads'=>'नयाँ अपलोडहरू','Move new uploads to Zinn® storage as they arrive'=>'नयाँ अपलोडहरू आउने बित्तिकै तिनीहरूलाई Zinn® भण्डारणमा सार्नुहोस्','Existing media'=>'अवस्थित मिडिया','Keep moving the media library that is already here'=>'पहिले नै यहाँ रहेको मिडिया पुस्तकालय सार्न जारी राख्नुहोस्','A few files an hour, in the background, picking up where it left off. Turning this off pauses it; nothing already moved comes back.'=>'पृष्ठभूमिमा प्रति घण्टा केही फाइलहरू, रोकिएको ठाउँबाट जारी रहन्छ। यसलाई बन्द गर्नाले यो पज हुन्छ; पहिले नै सारिएको कुनै पनि कुरा फिर्ता आउँदैन।','Files per hourly pass'=>'प्रति घण्टा पास फाइलहरू','Each attachment is several files and every one is a full upload. Raise this on a fast host with a generous execution limit; lower it if passes are being cut short.'=>'प्रत्येक संलग्नकमा धेरै फाइलहरू हुन्छन् र प्रत्येक पूर्ण अपलोड हो। उदार कार्यान्वयन सीमा भएको द्रुत होस्टमा यसलाई बढाउनुहोस्; यदि प्रक्रियाहरू बीचमै रोकिइरहेका छन् भने यसलाई घटाउनुहोस्।','Leave files smaller than'=>'यो भन्दा सानो फाइलहरू छोड्नुहोस्','Kilobytes. A tiny icon costs more in the extra connection than it saves in disk, so there is rarely a reason to move one. Set to 0 to move everything.'=>'किलोबाइट्स। एउटा सानो आइकनले डिस्कमा बचत गर्ने भन्दा अतिरिक्त जडानमा बढी खर्च गर्छ, त्यसैले यसलाई सार्ने कारण विरलै हुन्छ। सबै कुरा सार्न 0 मा सेट गर्नुहोस्।','Never move these types'=>'यी प्रकारहरू कहिल्यै नसार्नुहोस्','Useful when a plugin reads a file straight off the disk — a font, a PDF a form builder stamps, an audio file a player seeks inside.'=>'जब कुनै प्लगइनले डिस्कबाट सीधा फाइल पढ्छ तब उपयोगी हुन्छ — फन्ट, फारम निर्माताले टिकट लगाएको PDF, प्लेयरले भित्र खोज्ने अडियो फाइल।','These two are the ones to be careful with — read each description before changing it.'=>'यी दुईसँग होसियार हुनुपर्छ — परिवर्तन गर्नु अघि प्रत्येक विवरण पढ्नुहोस्।','Serve from Zinn® storage'=>'Zinn® भण्डारणबाट सेवा दिनुहोस्','Point image and file addresses at Zinn® storage'=>'तस्वीर र फाइल ठेगानाहरूलाई Zinn® भण्डारणतर्फ निर्देशित गर्नुहोस्','Off, files are uploaded but still served from this server — which is the safe state while you check everything arrived. On, visitors are served from storage and this server stops carrying the traffic.'=>'निष्क्रिय हुँदा, फाइलहरू अपलोड हुन्छन् तर अझै पनि यसै सर्भरबाट उपलब्ध गराइन्छ — जुन सबै कुरा आइपुगेको छ भनी तपाईंले जाँच गर्दाको सुरक्षित अवस्था हो। सक्रिय हुँदा, आगन्तुकहरूलाई भण्डारणबाट सेवा दिइन्छ र यो सर्भरले ट्राफिक लिन बन्द गर्दछ।','Free the disk space'=>'डिस्क ठाउँ खाली गर्नुहोस्','Delete the local copy once every size has uploaded'=>'प्रत्येक आकार अपलोड भएपछि स्थानीय प्रतिलिपि मेटाउनुहोस्','This is the point of offloading, and it is also the irreversible half. Leave it off until “Serve from Zinn® storage” is on and you have checked your site — a local copy is the only thing that saves you if something was missed.'=>'अफलोड गर्नुको उद्देश्य यही हो, र यो उल्टाउन नसकिने आधा भाग पनि हो। “Zinn® भण्डारणबाट सेवा दिनुहोस्” सक्रिय नभएसम्म र तपाईंले आफ्नो साइट जाँच नगरेसम्म यसलाई बन्द नै राख्नुहोस् — यदि केही कुरा छुटेको भए तपाईंलाई बचाउने एक मात्र कुरा स्थानीय प्रतिलिपि हो।','Deleting local copies cannot be undone from this screen. Take a backup first — the Zinn® Connector plugin can do that for you.'=>'स्थानीय प्रतिलिपिहरू मेटाउने कार्य यस स्क्रिनबाट पूर्वावस्थामा फर्काउन सकिँदैन। पहिले ब्याकअप लिनुहोस् — Zinn® Connector प्लगइनले यो तपाईंको लागि गर्न सक्छ।','This site is not connected to Zinn® storage yet, so there is nowhere to move media to.'=>'यो साइट अझै Zinn® भण्डारणसँग जोडिएको छैन, त्यसैले मिडिया सार्नको लागि कुनै ठाउँ छैन।','%d attachment moved.'=>'%d संलग्नक सारियो।' . "\0" . '%d संलग्नकहरू सारियो।','This site is not connected to Zinn® storage.'=>'यो साइट Zinn® भण्डारणसँग जोडिएको छैन।','Nothing is wrong — it has simply not been paired yet. Media stays on this server until it is.'=>'कुनै खराबी छैन — यो अहिलेसम्म केवल जोडा बनाइएको छैन। नभएसम्म मिडिया यस सर्भरमा रहन्छ।','Connected, but the last upload failed.'=>'जडान भयो, तर पछिल्लो अपलोड असफल भयो।','Try a batch now'=>'अहिले एउटा ब्याच प्रयास गर्नुहोस्','Connected. Every attachment has been moved.'=>'जडान भयो। प्रत्येक संलग्नक सारिएको छ।','Connected. %1$s of %2$s attachments still on this server.'=>'जडान भयो। %2$s संलग्नहरू मध्ये %1$s अझै पनि यस सर्भरमा छन्।','Moved so far'=>'हालसम्म सारिएको','%1$s files, %2$s'=>'%1$s फाइलहरू, %2$s','Still on this server'=>'अझै पनि यस सर्भरमा','%1$s of %2$s attachments'=>'%2$s मध्ये %1$s संलग्नकहरू','Served from'=>'बाट सेवा दिइएको','this server'=>'यो सर्भर','Connect this site'=>'यो साइट जडान गर्नुहोस्','Open your Zinn Digital® dashboard, choose this site, open Files & databases, and press “Get a pairing code” under Images & video CDN. Paste the code below.'=>'आफ्नो Zinn Digital® ड्यासबोर्ड खोल्नुहोस्, यो साइट छान्नुहोस्, फाइलहरू र डेटाबेसहरू खोल्नुहोस्, र छविहरू र भिडियो CDN अन्तर्गत "पेयरिङ कोड प्राप्त गर्नुहोस्" थिच्नुहोस्। तल कोड टाँस्नुहोस्।','Pairing code'=>'जोडा बनाउने कोड','Disconnect this site'=>'यो साइट विच्छेद गर्नुहोस्','New uploads will stay on this server. Media already moved keeps working — its address does not change.'=>'नयाँ अपलोडहरू यस सर्भरमा रहनेछन्। पहिले नै सारिएको मिडियाले काम गर्न जारी राख्छ — यसको ठेगाना परिवर्तन हुँदैन।','You do not have permission to manage this site.'=>'तपाईंसँग यो साइट व्यवस्थापन गर्ने अनुमति छैन।','Paste the pairing code from your Zinn Digital® dashboard.'=>'तपाईंको Zinn Digital® ड्यासबोर्डबाट पेयरिङ कोड टाँस्नुहोस्।','Connected. New uploads will be stored with Zinn Digital® from now on, and your existing media will move in the background.'=>'जडान भयो। नयाँ अपलोडहरू अबदेखि Zinn Digital® मा भण्डार गरिनेछ, र तपाईंका अवस्थित मिडिया पृष्ठभूमिमा सारिनेछ।','Disconnected. Media already moved keeps working; new uploads stay on this server.'=>'विच्छेद गरियो। पहिले नै सारिएका मिडियाले काम गर्न जारी राख्छन्; नयाँ अपलोडहरू यसै सर्भरमा रहनेछन्।','That file could not be read from this server, so nothing was uploaded.'=>'त्यो फाइल यस सर्भरबाट पढ्न सकिएन, त्यसैले केही पनि अपलोड भएन।','This site could not stream the upload, so nothing was sent.'=>'यो साइटले अपलोड स्ट्रिम गर्न सकेन, त्यसैले केही पनि पठाइएन।','This file is %1$s and this site\'s PHP has no cURL, so the largest it can upload is %2$s.'=>'यो फाइल %1$s छ र यो साइटको PHP मा cURL छैन, त्यसैले यसले अपलोड गर्न सक्ने सबैभन्दा ठूलो आकार %2$s हो।','The upload could not be completed.'=>'अपलोड पूरा गर्न सकिएन।','Storage refused the upload (HTTP %d).'=>'भण्डारणले अपलोड अस्वीकार गर्‍यो (HTTP %d)।','Style preset'=>'शैली प्रिसेट','A starting point. Anything below overrides it.'=>'सुरुवाती बिन्दु। तलको कुनै पनि कुराले यसलाई अधिरोपण गर्दछ।','Use my own colours and sizes'=>'मेरो आफ्नै रङ र आकारहरू प्रयोग गर्नुहोस्','Leave this off and the preset is used exactly as it is.'=>'यसलाई बन्द नै छोड्नुहोस् र प्रिसेट जस्तो छ त्यस्तै प्रयोग हुनेछ।','See the Zinn Digital® release notes.'=>'Zinn Digital® विमोचन टिप्पणीहरू हेर्नुहोस्।','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Zinn® अपडेट सेवाले यस अपडेटका लागि डाउनलोड लिङ्क जारी गरेन। यो साइट Zinn® प्लेटफर्ममा पुग्न सक्छ भनी जाँच गर्नुहोस्, त्यसपछि फेरि प्रयास गर्नुहोस्।','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Zinn® अपडेट सेवा (%s) बाट अपडेट डाउनलोड गर्न सकिएन। केही मिनेटमा पुन: प्रयास गर्नुहोस्।','The downloaded update failed its integrity check and was not installed.'=>'डाउनलोड गरिएको अपडेटले आफ्नो अखण्डता जाँच पूरा गर्न सकेन र स्थापना गरिएन।']];